     1→import { Block, Text } from "@prototyp/skeletor";
     2→import { FlashList, type FlashListRef } from "@shopify/flash-list";
     3→import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
     4→import { useAtom } from "jotai";
     5→import {
     6→  addDateDividers,
     7→  getEventId,
     8→  getItemUniqueKey,
     9→  groupInfoEvents,
    10→} from "modules/matrix-client/utils";
    11→import { useRoomTimeline } from "modules/timeline/hooks";
    12→import { TimelineAtoms } from "modules/timeline/jotai";
    13→import {
    14→  filterSameStateKey,
    15→  handleIsPreviousSameSender,
    16→} from "modules/timeline/utils";
    17→import {
    18→  type FC,
    19→  useCallback,
    20→  useEffect,
    21→  useMemo,
    22→  useRef,
    23→  useState,
    24→} from "react";
    25→import {
    26→  Image,
    27→  KeyboardAvoidingView,
    28→  type NativeScrollEvent,
    29→  type NativeSyntheticEvent,
    30→  StyleSheet,
    31→} from "react-native";
    32→import {
    33→  Button,
    34→  ImageViewerModal,
    35→  Loading,
    36→  MemberDetailsBottomSheet,
    37→  VideoViewerModal,
    38→} from "shared/components";
    39→import { useMemberDetails } from "shared/hooks";
    40→import { DateDivider } from "../date-divider";
    41→import { GroupedInfoMessages } from "../grouped-info-messages";
    42→import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
    43→import { RoomInput } from "../room-input";
    44→import { SingleMessageType } from "../single-message-type";
    45→
    46→interface Props {
    47→  room: RoomInterface;
    48→  roomId: string;
    49→}
    50→
    51→export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
    52→  const flatListRef = useRef<FlashListRef<TimelineListItem>>(null);
    53→  const isAtBottomRef = useRef(true);
    54→  const lastEventKeyRef = useRef<string | undefined>(undefined);
    55→  const [showScrollDown, setShowScrollDown] = useState(false);
    56→  const {
    57→    events,
    58→    loadingMessage,
    59→    refreshing,
    60→    updateTrigger,
    61→    isDirect,
    62→    loadMoreMessages,
    63→    markAsRead,
    64→  } = useRoomTimeline({
    65→    room,
    66→    roomId,
    67→  });
    68→  const [scrollToEventId, setScrollToEventId] = useAtom(
    69→    TimelineAtoms.scrollToEventId,
    70→  );
    71→  const {
    72→    selectedMember,
    73→    isBottomSheetOpen,
    74→    openMemberDetails,
    75→    closeMemberDetails,
    76→  } = useMemberDetails();
    77→
    78→  const sortedEvents = useMemo(() => {
    79→    const sorted = [...events].sort(
    80→      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    81→    );
    82→
    83→    return filterSameStateKey(sorted);
    84→  }, [events]);
    85→
    86→  const eventsWithDividers = useMemo(() => {
    87→    return groupInfoEvents(addDateDividers(sortedEvents));
    88→  }, [sortedEvents]);
    89→
    90→  const handleScrollToEvent = useCallback(
    91→    (eventId: string) => {
    92→      const index = eventsWithDividers.findIndex(
    93→        (item) =>
    94→          item.type === "event" && getEventId(item.data) === eventId,
    95→      );
    96→      if (index === -1) return;
    97→
    98→      flatListRef.current?.scrollToIndex({
    99→        index,
   100→        animated: true,
   101→        viewPosition: 0.5,
   102→      });
   103→    },
   104→    [eventsWithDividers],
   105→  );
   106→
   107→  useEffect(() => {
   108→    if (!scrollToEventId) return;
   109→    handleScrollToEvent(scrollToEventId);
   110→    setScrollToEventId(null);
   111→  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
   112→
   113→  const handleLoadMore = async () => {
   114→    setShowScrollDown(false);
   115→    await loadMoreMessages();
   116→  };
   117→
   118→  const handleScrollDown = () => {
   119→    flatListRef.current?.scrollToEnd({ animated: true });
   120→    setShowScrollDown(false);
   121→  };
   122→
   123→  const handleOnScroll = ({
   124→    nativeEvent,
   125→  }: NativeSyntheticEvent<NativeScrollEvent>) => {
   126→    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
   127→    const paddingToBottom = 100;
   128→    const atBottom =
   129→      layoutMeasurement.height + contentOffset.y >=
   130→      contentSize.height - paddingToBottom;
   131→    isAtBottomRef.current = atBottom;
   132→    if (!atBottom) return;
   133→    setShowScrollDown(false);
   134→    markAsRead();
   135→  };
   136→
   137→  const handleContentSizeChange = () => {
   138→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   139→    const lastEventKey = lastEvent
   140→      ? (getItemUniqueKey(lastEvent) ?? undefined)
   141→      : undefined;
   142→    const isNewEvent = lastEventKey !== lastEventKeyRef.current;
   143→    lastEventKeyRef.current = lastEventKey;
   144→    if (!isNewEvent || !lastEvent?.isOwn) return;
   145→    flatListRef.current?.scrollToEnd({ animated: false });
   146→    setTimeout(() => {
   147→      flatListRef.current?.scrollToEnd({ animated: false });
   148→    }, 100);
   149→  };
   150→
   151→  useEffect(() => {
   152→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   153→    if (isAtBottomRef.current || lastEvent?.isOwn) return;
   154→
   155→    setShowScrollDown(true);
   156→  }, [isAtBottomRef.current, sortedEvents]);
   157→
   158→  return (
   159→    <>
   160→      <KeyboardAvoidingView style={styles.flex} behavior="padding">
   161→        {loadingMessage && <Loading />}
   162→        <FlashList
   163→          ref={flatListRef}
   164→          data={eventsWithDividers}
   165→          keyExtractor={(item) => {
   166→            if (item.type === "divider") return item.id;
   167→            if (item.type === "group") return item.id;
   168→
   169→            return getItemUniqueKey(item.data) ?? "";
   170→          }}
   171→          maintainVisibleContentPosition={{
   172→            startRenderingFromBottom: true,
   173→          }}
   174→          extraData={updateTrigger}
   175→          contentContainerStyle={styles.listContent}
   176→          refreshing={refreshing}
   177→          onContentSizeChange={handleContentSizeChange}
   178→          onRefresh={handleLoadMore}
   179→          onScroll={handleOnScroll}
   180→          renderItem={({ item }) => {
   181→            if (item.type === "divider") {
   182→              return <DateDivider date={item.date} />;
   183→            }
   184→
   185→            if (item.type === "group") {
   186→              return <GroupedInfoMessages events={item.events} />;
   187→            }
   188→
   189→            return (
   190→              <SingleMessageType
   191→                event={item.data}
   192→                isPreviousSameSender={handleIsPreviousSameSender(
   193→                  isDirect,
   194→                  sortedEvents,
   195→                  item.data,
   196→                )}
   197→                onMemberPress={openMemberDetails}
   198→              />
   199→            );
   200→          }}
   201→        />
   202→
   203→        <RoomInput roomId={roomId} />
   204→      </KeyboardAvoidingView>
   205→
   206→      <MessageContentBottomSheet roomId={roomId} />
   207→
   208→      <MemberDetailsBottomSheet
   209→        isBottomSheetOpen={isBottomSheetOpen}
   210→        selectedMember={selectedMember}
   211→        roomId={roomId}
   212→        onClose={closeMemberDetails}
   213→      />
   214→
   215→      {showScrollDown && (
   216→        <Block
   217→          absolute
   218→          offsets={{ right: 0, bottom: 100 }}
   219→          align="center"
   220→          justify="center"
   221→          width="100%"
   222→        >
   223→          <Button.Outline size="medium" onPress={handleScrollDown}>
   224→            <Text>New messages</Text>
   225→            <Image source={require("assets/icons/arrow-down.png")} />
   226→          </Button.Outline>
   227→        </Block>
   228→      )}
   229→
   230→      <ImageViewerModal />
   231→      <VideoViewerModal />
   232→    </>
   233→  );
   234→};
   235→
   236→const styles = StyleSheet.create({
   237→  flex: {
   238→    flex: 1,
   239→  },
   240→  listContent: {
   241→    paddingHorizontal: 20,
   242→    paddingTop: 12,
   243→    paddingBottom: 20,
   244→  },
   245→});
