    26→  const hasShield = isRed || isGrey;
    27→  const shieldMessage =
    28→    shieldState && "inner" in shieldState ? shieldState.inner.message : "";
    29→
    30→  return (
    31→    <>
    32→      {hasShield && !isUser ? (
    33→        <Button.Wrapper onPress={() => setModalVisible(true)} hitSlop={12}>
    34→          <Block
    35→            flexDirection={isUser ? "row" : "row-reverse"}
    36→            gap={4}
    37→            align="center"
    38→          >
