    42→              tintColor={Colors.error}
    43→            />
    44→            <Text size={TextSize.tiny} color={Colors.error}>
    45→              {format(Number(event.timestamp), "HH:mm")}
    46→            </Text>
    47→          </Block>
    48→        </Button.Wrapper>
