    50→        <Block flexDirection="row" gap={8} align="center">
    51→          {isUser && <DeliveryStatus event={event} />}
    52→          <Text size={TextSize.tiny} color={Colors.white50}>
    53→            {format(Number(event.timestamp), "HH:mm")}
    54→          </Text>
    55→        </Block>
    56→      )}
